    },
    {
      "benefit": "CI",
      "years": [2021, 2021],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "Peak A/E 1.327 (+0.35 vs baseline), immediate reversion",
      "confidence": 0.85,
      "evidence": [
        "ae_ci_by_year.csv shows isolated 2021 spike to 1.327, reverting to 0.95-1.01 in 2022-2024; empirical SD x6.0 Poisson indicates volatility but 2021 excursion is distinct and unsupported by gradual build-up"
      ],
      "recommended_action": "Analyze 2021 CI claims for disease prevalence changes, large group events, or reporting/coding shifts. Test IBNR adequacy and review CI pricing margins."
    }
  ]
}

